-- 0007_docs.sql — obohatenie dokumentov (parcely+druh pozemku, stavby, tituly/ťarchy). Aditívne.
CREATE TABLE IF NOT EXISTS lv_parcels (id INTEGER PRIMARY KEY AUTOINCREMENT, dataset_id TEXT NOT NULL, lv_no INTEGER NOT NULL, register TEXT NOT NULL, parcel_no TEXT NOT NULL, area_m2 INTEGER NOT NULL DEFAULT 0, drp_code INTEGER, drp_text TEXT, placement TEXT);
CREATE TABLE IF NOT EXISTS lv_buildings (id INTEGER PRIMARY KEY AUTOINCREMENT, dataset_id TEXT NOT NULL, lv_no INTEGER NOT NULL, descr TEXT NOT NULL, on_parcel TEXT);
CREATE TABLE IF NOT EXISTS lv_titles (id INTEGER PRIMARY KEY AUTOINCREMENT, dataset_id TEXT NOT NULL, lv_no INTEGER NOT NULL, kind TEXT NOT NULL, txt TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_lv_parcels ON lv_parcels(dataset_id, lv_no);
CREATE INDEX IF NOT EXISTS ix_lv_buildings ON lv_buildings(dataset_id, lv_no);
CREATE INDEX IF NOT EXISTS ix_lv_titles ON lv_titles(dataset_id, lv_no);
DELETE FROM lv_parcels;
DELETE FROM lv_buildings;
DELETE FROM lv_titles;
-- WMS auto-connect pre existujúce seedované k.ú. (obe Žilinský kraj → ESKN ZA)
